"""Generate docs/controls-register.md from metamodel/controls.json: every control that enforces the rulebook (metamodel),
where it runs, where its outcome is recorded, what monitors it, and the known gaps.
Usage: python -m sdem.controls [--check]
"""
import argparse, json
from pathlib import Path

from .metamodel import ROOT

SRC = ROOT / 'metamodel' / 'controls.json'
OUT = ROOT / 'docs' / 'controls-register.md'


def render():
    d = json.loads(SRC.read_text(encoding='utf-8'))
    out = ['# SDEM — Controls register', '',
           '> Generated by `python -m sdem.controls` from `metamodel/controls.json`; CI fails if it is stale.', '',
           'A **control** is an automatic check that enforces a rule of the rulebook (the metamodel). This register says, for each one, what it enforces, where it is built, when it runs, **where its outcome is recorded**, and **what monitors it**.', '',
           f"**Monitoring today:** {d['monitoring_today']}", '',
           '## Controls', '']
    res = ROOT / 'docs' / 'evidence' / 'use-case-example-1' / 'results.json'
    last = {c['id']: c for c in json.loads(res.read_text(encoding='utf-8'))['controls']} if res.exists() else {}
    when = json.loads(res.read_text(encoding='utf-8'))['run_date'] if res.exists() else None
    if when: out += [f"**Last tested:** [use-case example 1](use-case-example-1.md), run {when} — good data must be accepted, bad data rejected; evidence in [`evidence/use-case-example-1/`](evidence/use-case-example-1/manifest.json).", '']
    out += ['| ID | Rule area | Enforces | Built in | Runs | Outcome recorded in | Monitored by | Last tested (good · bad) |', '|---|---|---|---|---|---|---|---|']
    out += [f"| {c['id']} | {c['rule_area']} | {c['control']} | {c['implemented_in']} | {c['runs']} | {c['outcome_recorded_in']} | {c['monitored_by']} | {(last[c['id']]['good'] + ' · ' + last[c['id']]['bad']) if c['id'] in last else 'not tested'} |" for c in d['controls']]
    out += ['', '## Gaps — rules nothing enforces', '', '| ID | Rule area | Not controlled | Risk |', '|---|---|---|---|']
    out += [f"| {g['id']} | {g['rule_area']} | {g['not_controlled']} | {g['risk']} |" for g in d['gaps']]
    out += ['', 'Each control is demonstrated both ways — accepting good data and rejecting bad — in [`use-case-example-1.md`](use-case-example-1.md).', '']
    return '\n'.join(out)


def main(argv=None):
    ap = argparse.ArgumentParser(prog='sdem-controls'); ap.add_argument('--check', action='store_true'); a = ap.parse_args(argv)
    t = render()
    if a.check:
        ok = OUT.exists() and OUT.read_text(encoding='utf-8') == t
        print(f"{OUT.name}: {'up to date' if ok else 'STALE: regenerate with python -m sdem.controls'}"); return 0 if ok else 1
    OUT.write_text(t, encoding='utf-8'); print(f'wrote {OUT.relative_to(ROOT)}'); return 0


if __name__ == '__main__':
    raise SystemExit(main())
